// Design lint (design-system-tokens: "Raw value in a component").
//
// The rules live in site/.oxlintrc.json, copied verbatim from
// design/source/_ds/_adherence.oxlintrc.json (the token allow-list in "x-omelette" is generated by
// scripts/gen-lint-allowlist.mjs). oxlint has no `no-restricted-syntax`, so ESLint executes the
// selectors of that file through the local rule `design/adherence`, as warnings.
import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';

const rcPath = resolve(import.meta.dirname, '../.oxlintrc.json');

/** Selector/message pairs of the `no-restricted-syntax` rule in .oxlintrc.json. */
export function readAdherenceSelectors(path = rcPath) {
  const rc = JSON.parse(readFileSync(path, 'utf8'));
  const [, ...entries] = rc.rules['no-restricted-syntax'];
  return entries;
}

const adherence = {
  meta: { type: 'suggestion', schema: [], messages: { raw: '{{message}}' } },
  create(context) {
    const visitors = {};
    for (const { selector, message } of readAdherenceSelectors()) {
      visitors[selector] = (node) => context.report({ node, messageId: 'raw', data: { message } });
    }
    return visitors;
  },
};

export const designPlugin = { rules: { adherence } };

export const designLintConfigs = [
  {
    name: 'ws-B/design lint',
    files: ['app/**/*.{ts,tsx}', 'components/**/*.{ts,tsx}', 'hooks/**/*.{ts,tsx}', 'context/**/*.{ts,tsx}'],
    ignores: ['**/*.test.{ts,tsx}'],
    plugins: { design: designPlugin },
    rules: { 'design/adherence': 'warn' },
  },
];
